sysauto_script.script:
var propertyGr = new GlideRecord('x_snc_flowops_property_table');
propertyGr.query();
var today = new GlideDate();

while (propertyGr.next()) {
    var propertySysId = propertyGr.getUniqueValue();
    var propName = propertyGr.getValue('name') || propertyGr.getDisplayValue() || 'Unknown Property';

    var openCases = 0;
    var caseGr = new GlideAggregate('x_snc_flowops_guest_case');
    caseGr.addQuery('property', propertySysId);
    caseGr.addQuery('status', 'open');
    caseGr.addAggregate('COUNT');
    caseGr.query();
    if (caseGr.next()) {
        openCases = parseInt(caseGr.getAggregate('COUNT'), 10) || 0;
    }

    var payload = {
        property: propName,
        property_id: propertySysId,
        period: "daily",
        metrics: {
            open_work_orders: openCases,
            total_requests: 0,
            sla_breach_pct: 0,
            guest_satisfaction_score: 0,
            vendor_average_rating: 0,
            avg_response_time_hours: 0
        }
    };

    var request = new sn_ws.RESTMessageV2('FO_AI_Backend', 'OperationsIntelligence');
    request.setRequestHeader('x-flowops-api-key', gs.getProperty('x_snc_flowops.ai_api_key'));
    request.setRequestHeader('Content-Type', 'application/json');
    request.setRequestBody(JSON.stringify(payload));

    var response = request.execute();
    var httpStatus = response.getStatusCode();
    var responseBody = response.getBody();

    gs.info('Status: ' + httpStatus);
    gs.info('Body: ' + responseBody);

    if (httpStatus === 200) {
        var aiResult = JSON.parse(responseBody);

        var OIGr = new GlideRecord('x_snc_flowops_operations_intelligence');
        OIGr.initialize();
        OIGr.setValue('property', propertySysId);
        OIGr.setValue('health_score', aiResult.health_score);
        OIGr.setValue('issues', JSON.stringify(aiResult.issues));
        OIGr.setValue('recommendations', JSON.stringify(aiResult.recommendations));
        OIGr.insert();
    }
}
